/// <reference path="../_import/_fibjs.d.ts" />
/**
 * @description 颜色模块
 * 
 *     颜色模块提供了一组颜色常量，用于设置控制台输出颜色。
 * 
 */
declare module 'colors' {
    /**
     * @description 是否支持颜色输出 
     */
    const hasColors: boolean;

    /**
     * @description 清除颜色 
     */
    const clear: string;

    /**
     * @description 默认颜色 
     */
    const normal: string;

    /**
     * @description 黑色 
     */
    const black: string;

    /**
     * @description 灰色 
     */
    const gray: string;

    /**
     * @description 红色 
     */
    const red: string;

    /**
     * @description 绿色 
     */
    const green: string;

    /**
     * @description 黄色 
     */
    const yellow: string;

    /**
     * @description 蓝色 
     */
    const blue: string;

    /**
     * @description 洋红 
     */
    const magenta: string;

    /**
     * @description 青色 
     */
    const cyan: string;

    /**
     * @description 白色 
     */
    const white: string;

    /**
     * @description 亮黑色 
     */
    const lightred: string;

    /**
     * @description 亮绿色 
     */
    const lightgreen: string;

    /**
     * @description 亮黄色 
     */
    const lightyellow: string;

    /**
     * @description 亮蓝色 
     */
    const lightblue: string;

    /**
     * @description 亮洋红 
     */
    const lightmagenta: string;

    /**
     * @description 亮青色 
     */
    const lightcyan: string;

    /**
     * @description 亮白色 
     */
    const lightwhite: string;

}

